/**
 * LRU cache with TTL. Entries expire after ttlMs; the cache holds at most
 * `capacity` entries and evicts the least-recently-used one when full.
 * Recency is tracked by Map insertion order: get/set move the key to the
 * most-recently-used end, and eviction removes the first (least-recently-used)
 * entry.
 */
export function createCache({ ttlMs, capacity, clock = () => Date.now() }) {
  const entries = new Map() // key -> { value, expiresAt }
  return {
    get(key) {
      const entry = entries.get(key)
      if (entry === undefined) return undefined
      if (clock() > entry.expiresAt) {
        entries.delete(key)
        return undefined
      }
      // mark as most recently used
      entries.delete(key)
      entries.set(key, entry)
      return entry.value
    },
    set(key, value) {
      const now = clock()
      if (entries.has(key)) {
        entries.delete(key)
      } else if (entries.size >= capacity) {
        // evict the least-recently-used entry (the first in Map order)
        const oldest = entries.keys().next().value
        entries.delete(oldest)
      }
      entries.set(key, { value, expiresAt: now + ttlMs })
    },
    size() {
      return entries.size
    },
    _raw() {
      return [...entries.entries()]
    },
  }
}

